bool resolve_bool_expr(struct xkb_context *ctx, const ExprDef *expr, bool *set_rtrn) {
    if (!ctx || !expr || !set_rtrn) {
        return false;
    }

    switch (expr->op) {
        case OP_CONST: {
            if (expr->type != TYPE_BOOL) {
                xkb_context_log(ctx, XKB_LOG_LEVEL_ERROR, "Constant is not a boolean.");
                return false;
            }
            *set_rtrn = expr->value.bool_val;
            return true;
        }

        case OP_IDENT: {
            if (strcmp(expr->ident, "true") == 0) {
                *set_rtrn = true;
                return true;
            } else if (strcmp(expr->ident, "false") == 0) {
                *set_rtrn = false;
                return true;
            } else {
                xkb_context_log(ctx, XKB_LOG_LEVEL_ERROR, "Unknown boolean identifier: %s", expr->ident);
                return false;
            }
        }

        case OP_FIELD: {
            xkb_context_log(ctx, XKB_LOG_LEVEL_ERROR, "Field references are not supported in boolean expressions.");
            return false;
        }

        case OP_NOT: {
            if (!resolve_bool_expr(ctx, expr->unary_expr, set_rtrn)) {
                return false;
            }
            *set_rtrn = !(*set_rtrn);
            return true;
        }

        default: {
            xkb_context_log(ctx, XKB_LOG_LEVEL_ERROR, "Unsupported operation in boolean expression.");
            return false;
        }
    }
}
